#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

int16_t interpreta_c2_16(uint16_t u);
int conta_bit_16(uint16_t u);
void formatta_bin16(uint16_t u, char out[20]);

int main(void) {
    char riga[128], bin[20], extra = '\0';
    int n = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &n, &extra) != 1 || n < 0 || n > 64) {
        fprintf(stderr, "Errore: numero campioni non valido.\n");
        return EXIT_FAILURE;
    }
    if (n == 0) {
        printf("Nessuna parola da analizzare.\n");
        return EXIT_SUCCESS;
    }
    uint64_t somma_u = 0;
    int64_t somma_s = 0;
    int16_t min_s = INT16_MAX, max_s = INT16_MIN;
    int negativi = 0, estremi = 0;
    for (int i = 0; i < n; ++i) {
        unsigned int v = 0;
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%u %c", &v, &extra) != 1 || v > UINT16_MAX) {
            fprintf(stderr, "Errore: parola a 16 bit non valida.\n");
            return EXIT_FAILURE;
        }
        uint16_t u = (uint16_t)v;
        int16_t s = interpreta_c2_16(u);
        formatta_bin16(u, bin);
        printf("#%d: hex=0x%04" PRIx16 " bin=%s u=%" PRIu16 " c2=%" PRId16 " bit1=%d\n",
               i, u, bin, u, s, conta_bit_16(u));
        somma_u += u;
        somma_s += s;
        if (s < min_s) { min_s = s; }
        if (s > max_s) { max_s = s; }
        if (s < 0) { ++negativi; }
        if (s == INT16_MIN || s == INT16_MAX) { ++estremi; }
    }
    printf("Somma unsigned: %" PRIu64 ", somma c2: %" PRId64 "\n", somma_u, somma_s);
    printf("Min c2: %" PRId16 ", max c2: %" PRId16 "\n", min_s, max_s);
    printf("Negativi: %d, estremi (INT16_MIN/MAX): %d\n", negativi, estremi);
    return EXIT_SUCCESS;
}

int16_t interpreta_c2_16(uint16_t u) {
    if ((u & 0x8000U) == 0U) { return (int16_t)u; }
    uint16_t mag = (uint16_t)((uint16_t)(~u) + 1U);
    return (mag == 0x8000U) ? INT16_MIN : (int16_t)(-(int32_t)mag);
}

int conta_bit_16(uint16_t u) {
    int c = 0;
    for (int b = 0; b < 16; ++b) {
        if ((u & (uint16_t)(1U << b)) != 0U) { ++c; }
    }
    return c;
}

void formatta_bin16(uint16_t u, char out[20]) {
    size_t pos = 0;
    for (int b = 15; b >= 0; --b) {
        out[pos++] = ((u & (uint16_t)(1U << b)) != 0U) ? '1' : '0';
        if (b > 0 && b % 4 == 0) { out[pos++] = '_'; }
    }
    out[pos] = '\0';
}

#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct istruzione {
    uint8_t opcode;
    uint8_t rd;
    uint8_t rs;
    uint8_t flags;
    int16_t imm;
} istruzione_t;

uint32_t codifica_istruzione(const istruzione_t *i);
istruzione_t decodifica_istruzione(uint32_t w);
uint32_t aggiorna_flags(uint32_t w, uint8_t set_m, uint8_t clr_m, uint8_t tog_m);

int main(void) {
    char riga[128], cmd[16], extra = '\0';
    int tot = 0;
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        if (strcmp(cmd, "ENC") == 0) {
            int op = 0, rd = 0, rs = 0, fl = 0, im = 0;
            if (sscanf(riga, "ENC %d %d %d %d %d %c", &op, &rd, &rs, &fl, &im, &extra) != 5 ||
                (op | rd | rs | fl) < 0 || (op | rd | rs | fl) > 15 ||
                im < INT16_MIN || im > INT16_MAX) {
                fprintf(stderr, "Errore: parametri ENC non validi.\n");
                return EXIT_FAILURE;
            }
            istruzione_t ist = {(uint8_t)op, (uint8_t)rd, (uint8_t)rs, (uint8_t)fl, (int16_t)im};
            printf("ENC -> 0x%08" PRIx32 "\n", codifica_istruzione(&ist));
        } else if (strcmp(cmd, "DEC") == 0) {
            unsigned int w_in = 0;
            if (sscanf(riga, "DEC %u %c", &w_in, &extra) != 1) {
                fprintf(stderr, "Errore: parametro DEC non valido.\n");
                return EXIT_FAILURE;
            }
            uint32_t w = (uint32_t)w_in;
            istruzione_t d = decodifica_istruzione(w);
            printf("DEC 0x%08" PRIx32 " -> op=%" PRIu8 " rd=%" PRIu8 " rs=%" PRIu8 " flags=0x%" PRIx8 " imm=%" PRId16 "\n",
                   w, d.opcode, d.rd, d.rs, d.flags, d.imm);
        } else if (strcmp(cmd, "FLG") == 0) {
            unsigned int w_in = 0;
            int s = 0, c = 0, t = 0;
            if (sscanf(riga, "FLG %u %d %d %d %c", &w_in, &s, &c, &t, &extra) != 4 ||
                (s | c | t) < 0 || (s | c | t) > 15) {
                fprintf(stderr, "Errore: parametri FLG non validi.\n");
                return EXIT_FAILURE;
            }
            uint32_t nw = aggiorna_flags((uint32_t)w_in, (uint8_t)s, (uint8_t)c, (uint8_t)t);
            printf("FLG 0x%08" PRIx32 " -> 0x%08" PRIx32 " (flags=0x%" PRIx8 ")\n",
                   (uint32_t)w_in, nw, (uint8_t)((nw >> 16) & 0x0FU));
        } else {
            fprintf(stderr, "Errore: comando sconosciuto.\n");
            return EXIT_FAILURE;
        }
        ++tot;
    }
    printf("Operazioni eseguite: %d\n", tot);
    return EXIT_SUCCESS;
}

uint32_t codifica_istruzione(const istruzione_t *i) {
    uint32_t imm_u = (uint32_t)(uint16_t)i->imm;
    return ((uint32_t)(i->opcode & 0x0FU) << 28) |
           ((uint32_t)(i->rd & 0x0FU) << 24) |
           ((uint32_t)(i->rs & 0x0FU) << 20) |
           ((uint32_t)(i->flags & 0x0FU) << 16) | imm_u;
}

istruzione_t decodifica_istruzione(uint32_t w) {
    uint16_t u = (uint16_t)(w & 0xFFFFU);
    int16_t imm = ((u & 0x8000U) == 0U) ? (int16_t)u :
                  ((u == 0x8000U) ? INT16_MIN : (int16_t)(-(int32_t)(uint16_t)((uint16_t)(~u) + 1U)));
    return (istruzione_t){
        .opcode = (uint8_t)((w >> 28) & 0x0FU),
        .rd = (uint8_t)((w >> 24) & 0x0FU),
        .rs = (uint8_t)((w >> 20) & 0x0FU),
        .flags = (uint8_t)((w >> 16) & 0x0FU),
        .imm = imm
    };
}

uint32_t aggiorna_flags(uint32_t w, uint8_t set_m, uint8_t clr_m, uint8_t tog_m) {
    uint8_t f = (uint8_t)((w >> 16) & 0x0FU);
    f = (uint8_t)(f | (set_m & 0x0FU));
    f = (uint8_t)(f & (uint8_t)~(clr_m & 0x0FU));
    f = (uint8_t)(f ^ (tog_m & 0x0FU));
    return (w & ~(0x0FU << 16)) | ((uint32_t)f << 16);
}

#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum tipo_cella : int {
    CELLA_VUOTA = 0, CELLA_INT = 1, CELLA_REAL = 2, CELLA_TESTO = 3, CELLA_ERR = 4
} tipo_cella_t;

typedef union dato_cella {
    int64_t intero;
    double reale;
    char testo[16];
    int cod_err;
} dato_cella_t;

typedef struct cella {
    tipo_cella_t tipo;
    dato_cella_t dato;
} cella_t;

cella_t somma_celle(const cella_t *a, const cella_t *b);
void stampa_cella(int idx, const cella_t *c);

int main(void) {
    cella_t foglio[8] = {};
    char riga[128], cmd[16], buf[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        int idx = 0, i1 = 0, i2 = 0;
        long long v_int = 0;
        double v_real = 0.0;
        if (strcmp(cmd, "INT") == 0 && sscanf(riga, "INT %d %lld %c", &idx, &v_int, &extra) == 2 && idx >= 0 && idx < 8) {
            foglio[idx] = (cella_t){.tipo = CELLA_INT, .dato = {.intero = (int64_t)v_int}};
        } else if (strcmp(cmd, "REAL") == 0 && sscanf(riga, "REAL %d %lf %c", &idx, &v_real, &extra) == 2 && idx >= 0 && idx < 8) {
            foglio[idx] = (cella_t){.tipo = CELLA_REAL, .dato = {.reale = v_real}};
        } else if (strcmp(cmd, "TXT") == 0 && sscanf(riga, "TXT %d %15s %c", &idx, buf, &extra) == 2 && idx >= 0 && idx < 8) {
            foglio[idx] = (cella_t){.tipo = CELLA_TESTO};
            strncpy(foglio[idx].dato.testo, buf, sizeof(foglio[idx].dato.testo) - 1);
        } else if (strcmp(cmd, "ADD") == 0 && sscanf(riga, "ADD %d %d %d %c", &idx, &i1, &i2, &extra) == 3 &&
                   (idx | i1 | i2) >= 0 && idx < 8 && i1 < 8 && i2 < 8) {
            foglio[idx] = somma_celle(&foglio[i1], &foglio[i2]);
        } else if (strcmp(cmd, "CLR") == 0 && sscanf(riga, "CLR %d %c", &idx, &extra) == 1 && idx >= 0 && idx < 8) {
            foglio[idx] = (cella_t){.tipo = CELLA_VUOTA};
        } else {
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    printf("Verifica sizeof(union) <= sizeof(struct): %d\n", sizeof(dato_cella_t) <= sizeof(cella_t));
    int num = 0, txt = 0, err = 0;
    for (int i = 0; i < 8; ++i) {
        stampa_cella(i, &foglio[i]);
        if (foglio[i].tipo == CELLA_INT || foglio[i].tipo == CELLA_REAL) { ++num; }
        else if (foglio[i].tipo == CELLA_TESTO) { ++txt; }
        else if (foglio[i].tipo == CELLA_ERR) { ++err; }
    }
    printf("Riepilogo -> numeriche: %d, testo: %d, errori: %d\n", num, txt, err);
    return EXIT_SUCCESS;
}

cella_t somma_celle(const cella_t *a, const cella_t *b) {
    if (a->tipo == CELLA_ERR) { return *a; }
    if (b->tipo == CELLA_ERR) { return *b; }
    if (a->tipo == CELLA_VUOTA || b->tipo == CELLA_VUOTA) {
        return (cella_t){.tipo = CELLA_ERR, .dato = {.cod_err = 10}};
    }
    if (a->tipo == CELLA_TESTO || b->tipo == CELLA_TESTO) {
        return (cella_t){.tipo = CELLA_ERR, .dato = {.cod_err = 20}};
    }
    if (a->tipo == CELLA_INT && b->tipo == CELLA_INT) {
        return (cella_t){.tipo = CELLA_INT, .dato = {.intero = a->dato.intero + b->dato.intero}};
    }
    double va = (a->tipo == CELLA_INT) ? (double)a->dato.intero : a->dato.reale;
    double vb = (b->tipo == CELLA_INT) ? (double)b->dato.intero : b->dato.reale;
    return (cella_t){.tipo = CELLA_REAL, .dato = {.reale = va + vb}};
}

void stampa_cella(int idx, const cella_t *c) {
    switch (c->tipo) {
        case CELLA_INT: printf("C%d [INT]: %" PRId64 "\n", idx, c->dato.intero); break;
        case CELLA_REAL: printf("C%d [REAL]: %.2f\n", idx, c->dato.reale); break;
        case CELLA_TESTO: printf("C%d [TXT]: %s\n", idx, c->dato.testo); break;
        case CELLA_ERR: printf("C%d [ERR]: #%d\n", idx, c->dato.cod_err); break;
        default: break;
    }
}

#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct porta_bf {
    unsigned int attiva : 1;
    unsigned int duplex : 1;
    unsigned int velocita : 2;
    unsigned int vlan : 4;
    unsigned int priorita : 3;
    unsigned int : 5;
} porta_bf_t;

uint16_t esporta_porta(const porta_bf_t *p);
porta_bf_t importa_porta(uint16_t reg);

int main(void) {
    porta_bf_t porte[4] = {};
    char riga[128], cmd[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        int id = 0, a = 0, d = 0, v = 0, vl = 0, pr = 0;
        unsigned int reg_in = 0;
        if (strcmp(cmd, "SET") == 0 &&
            sscanf(riga, "SET %d %d %d %d %d %d %c", &id, &a, &d, &v, &vl, &pr, &extra) == 6 &&
            id >= 0 && id < 4 && (a | d) >= 0 && (a | d) <= 1 &&
            v >= 0 && v <= 3 && vl >= 0 && vl <= 15 && pr >= 0 && pr <= 7) {
            porte[id] = (porta_bf_t){
                .attiva = (unsigned int)a, .duplex = (unsigned int)d,
                .velocita = (unsigned int)v, .vlan = (unsigned int)vl, .priorita = (unsigned int)pr
            };
        } else if (strcmp(cmd, "IMP") == 0 &&
                   sscanf(riga, "IMP %d %u %c", &id, &reg_in, &extra) == 2 &&
                   id >= 0 && id < 4 && reg_in <= 0x07FFU) {
            porte[id] = importa_porta((uint16_t)reg_in);
        } else if (strcmp(cmd, "INC_PRIO") == 0 &&
                   sscanf(riga, "INC_PRIO %d %c", &id, &extra) == 1 && id >= 0 && id < 4) {
            porte[id].priorita = (unsigned int)(porte[id].priorita + 1U);
        } else {
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    int attive = 0;
    for (int i = 0; i < 4; ++i) {
        uint16_t r = esporta_porta(&porte[i]);
        if (porte[i].attiva != 0U) { ++attive; }
        printf("P%d: attiva=%u duplex=%u vel=%u vlan=%u prio=%u -> reg=0x%04" PRIx16 "\n",
               i, porte[i].attiva, porte[i].duplex, porte[i].velocita,
               porte[i].vlan, porte[i].priorita, r);
    }
    printf("Porte attive: %d\n", attive);
    return EXIT_SUCCESS;
}

uint16_t esporta_porta(const porta_bf_t *p) {
    return (uint16_t)((p->attiva & 1U) |
                      ((p->duplex & 1U) << 1) |
                      ((p->velocita & 3U) << 2) |
                      ((p->vlan & 15U) << 4) |
                      ((p->priorita & 7U) << 8));
}

porta_bf_t importa_porta(uint16_t reg) {
    return (porta_bf_t){
        .attiva = (unsigned int)(reg & 1U),
        .duplex = (unsigned int)((reg >> 1) & 1U),
        .velocita = (unsigned int)((reg >> 2) & 3U),
        .vlan = (unsigned int)((reg >> 4) & 15U),
        .priorita = (unsigned int)((reg >> 8) & 7U)
    };
}

#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void scrivi_u16_be(uint8_t b[2], uint16_t v) {
    b[0] = (uint8_t)((v >> 8) & 0xFFU);
    b[1] = (uint8_t)(v & 0xFFU);
}

void scrivi_u32_be(uint8_t b[4], uint32_t v) {
    b[0] = (uint8_t)((v >> 24) & 0xFFU);
    b[1] = (uint8_t)((v >> 16) & 0xFFU);
    b[2] = (uint8_t)((v >> 8) & 0xFFU);
    b[3] = (uint8_t)(v & 0xFFU);
}

uint16_t leggi_u16_be(const uint8_t b[2]) {
    return (uint16_t)(((uint16_t)b[0] << 8) | (uint16_t)b[1]);
}

uint32_t leggi_u32_be(const uint8_t b[4]) {
    return ((uint32_t)b[0] << 24) | ((uint32_t)b[1] << 16) |
           ((uint32_t)b[2] << 8) | (uint32_t)b[3];
}

uint16_t swap_u16(uint16_t v) {
    return (uint16_t)((v >> 8) | (v << 8));
}

uint32_t swap_u32(uint32_t v) {
    return ((v >> 24) & 0x000000FFU) | ((v >> 8) & 0x0000FF00U) |
           ((v << 8) & 0x00FF0000U) | ((v << 24) & 0xFF000000U);
}

void stampa_8byte(const char *pref, const uint8_t b[8]) {
    printf("%s:", pref);
    for (int i = 0; i < 8; ++i) { printf(" %02" PRIx8, b[i]); }
    printf("\n");
}

int main(void) {
    char riga[128], cmd[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        if (strcmp(cmd, "PACK") == 0) {
            unsigned int id = 0, len = 0, ch = 0;
            if (sscanf(riga, "PACK %u %u %u %c", &id, &len, &ch, &extra) != 3 ||
                id > UINT16_MAX || len > UINT16_MAX) {
                fprintf(stderr, "Errore: parametri PACK non validi.\n");
                return EXIT_FAILURE;
            }
            uint8_t be[8], le[8];
            scrivi_u16_be(be, (uint16_t)id);
            scrivi_u16_be(be + 2, (uint16_t)len);
            scrivi_u32_be(be + 4, (uint32_t)ch);
            scrivi_u16_be(le, swap_u16((uint16_t)id));
            scrivi_u16_be(le + 2, swap_u16((uint16_t)len));
            scrivi_u32_be(le + 4, swap_u32((uint32_t)ch));
            stampa_8byte("BE", be);
            stampa_8byte("LE", le);
        } else if (strcmp(cmd, "UNPACK_BE") == 0 || strcmp(cmd, "UNPACK_LE") == 0) {
            unsigned int v[8];
            if (sscanf(riga, "%*s %u %u %u %u %u %u %u %u %c",
                       &v[0], &v[1], &v[2], &v[3], &v[4], &v[5], &v[6], &v[7], &extra) != 8) {
                fprintf(stderr, "Errore: byte UNPACK non validi.\n");
                return EXIT_FAILURE;
            }
            uint8_t b[8];
            for (int i = 0; i < 8; ++i) {
                if (v[i] > UINT8_MAX) { return EXIT_FAILURE; }
                b[i] = (uint8_t)v[i];
            }
            uint16_t id = leggi_u16_be(b), len = leggi_u16_be(b + 2);
            uint32_t ch = leggi_u32_be(b + 4);
            if (strcmp(cmd, "UNPACK_LE") == 0) {
                id = swap_u16(id); len = swap_u16(len); ch = swap_u32(ch);
            }
            printf("%s -> id=%" PRIu16 " len=%" PRIu16 " chiave=0x%08" PRIx32 "\n", cmd, id, len, ch);
        } else {
            fprintf(stderr, "Errore: comando sconosciuto.\n");
            return EXIT_FAILURE;
        }
    }
    return EXIT_SUCCESS;
}

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct rec_sparso { uint8_t t; uint32_t v; uint8_t f; uint16_t c; } rec_sparso_t;
typedef struct rec_compatto { uint32_t v; uint16_t c; uint8_t t; uint8_t f; } rec_compatto_t;

typedef struct campo_spec {
    char nome[16];
    size_t align;
    size_t bytes;
    size_t offset;
} campo_spec_t;

size_t allinea_su(size_t pos, size_t a) {
    size_t r = pos % a;
    return (r == 0) ? pos : (pos + (a - r));
}

size_t calcola_layout(campo_spec_t v[], size_t n, size_t *align_out, size_t *pad_out) {
    size_t pos = 0, max_a = 1, pad = 0;
    for (size_t i = 0; i < n; ++i) {
        if (v[i].align > max_a) { max_a = v[i].align; }
        size_t allineato = allinea_su(pos, v[i].align);
        pad += allineato - pos;
        v[i].offset = allineato;
        pos = allineato + v[i].bytes;
    }
    size_t tot = allinea_su(pos, max_a);
    pad += tot - pos;
    *align_out = max_a;
    *pad_out = pad;
    return tot;
}

int main(void) {
    char riga[128], extra = '\0';
    int n_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &n_in, &extra) != 1 || n_in < 1 || n_in > 20) {
        fprintf(stderr, "Errore: numero campi non valido.\n");
        return EXIT_FAILURE;
    }
    size_t n = (size_t)n_in;
    campo_spec_t orig[20] = {}, ord[20] = {};
    for (size_t i = 0; i < n; ++i) {
        int d = 0, cnt = 0;
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%15s %d %d %c", orig[i].nome, &d, &cnt, &extra) != 3 ||
            (d != 1 && d != 2 && d != 4 && d != 8) || cnt < 1 || cnt > 16) {
            fprintf(stderr, "Errore: specifica campo non valida.\n");
            return EXIT_FAILURE;
        }
        orig[i].align = (size_t)d;
        orig[i].bytes = (size_t)d * (size_t)cnt;
        ord[i] = orig[i];
    }
    for (size_t i = 1; i < n; ++i) {
        campo_spec_t chiave = ord[i];
        size_t j = i;
        while (j > 0 && ord[j - 1].align < chiave.align) {
            ord[j] = ord[j - 1];
            --j;
        }
        ord[j] = chiave;
    }
    size_t a_orig = 0, p_orig = 0, a_ott = 0, p_ott = 0;
    size_t s_orig = calcola_layout(orig, n, &a_orig, &p_orig);
    size_t s_ott = calcola_layout(ord, n, &a_ott, &p_ott);
    printf("Verifica struct C -> sparso: size=%zu align=%zu off_v=%zu, compatto: size=%zu align=%zu off_c=%zu\n",
           sizeof(rec_sparso_t), alignof(rec_sparso_t), offsetof(rec_sparso_t, v),
           sizeof(rec_compatto_t), alignof(rec_compatto_t), offsetof(rec_compatto_t, c));
    printf("Layout originale:\n");
    for (size_t i = 0; i < n; ++i) {
        printf("  %s: off=%zu dim=%zu align=%zu\n", orig[i].nome, orig[i].offset, orig[i].bytes, orig[i].align);
    }
    printf("Originale -> size=%zu align=%zu padding=%zu\n", s_orig, a_orig, p_orig);
    printf("Ottimizzato -> size=%zu align=%zu padding=%zu (risparmio=%zu byte)\n",
           s_ott, a_ott, p_ott, s_orig - s_ott);
    return EXIT_SUCCESS;
}
